mapper.select:
SELECT id, name, slug, lifecycle_state AS lifecycleState
FROM organization
WHERE id = #{orgId}

SELECT EXISTS(
  SELECT 1
  FROM org_member
  WHERE org_id = #{orgId}
    AND user_id = #{userId}
    AND org_role IN ('admin', 'owner')
  FOR SHARE
)

mapper.delete:
DELETE FROM tenant_operation_lease
WHERE workspace_id = #{workspaceId}
  AND lease_kind = #{leaseKind}
  AND lease_token = #{leaseToken}

mapper.select:
SELECT EXISTS(
  SELECT 1
  FROM tenant_operation_lease
  WHERE workspace_id = #{workspaceId}
    AND lease_kind = #{leaseKind}
    AND lease_token = #{leaseToken}
  FOR SHARE
)

SELECT COUNT(*)
FROM tenant_operation_lease
WHERE workspace_id = #{workspaceId} AND lease_kind = #{leaseKind}

SELECT COUNT(*)
FROM tenant_operation_lease
WHERE org_id = #{orgId}
  AND lease_kind = #{leaseKind}
  AND created_at > NOW(6) - INTERVAL #{maxAgeSeconds} SECOND

mapper.delete:
DELETE FROM tenant_operation_lease
WHERE lease_kind = #{leaseKind}
  AND created_at <= NOW(6) - INTERVAL #{maxAgeSeconds} SECOND
LIMIT #{limit}

mapper.update:
UPDATE workspace
SET lifecycle_state = 'tearing_down'
WHERE org_id = #{orgId} AND id = #{workspaceId}

UPDATE organization
SET lifecycle_state = 'tearing_down'
WHERE id = #{orgId}

UPDATE sso_connection
SET jit_workspace_id = NULL
WHERE org_id = #{orgId} AND jit_workspace_id = #{workspaceId}

mapper.delete:
DELETE FROM federated_identity
WHERE org_id = #{orgId}
LIMIT #{limit}

mapper.select:
SELECT COUNT(*)
FROM data_subject_request
WHERE org_id = #{orgId}
  AND subject_workspace_id = #{workspaceId}
  AND status NOT IN ('closed', 'refused')

mapper.delete:
DELETE FROM workspace
WHERE org_id = #{orgId} AND id = #{workspaceId}
  AND lifecycle_state = 'tearing_down'

mapper.select:
SELECT COUNT(*)
FROM workspace
WHERE org_id = #{orgId}

SELECT COUNT(*)
FROM tenant_cleanup_tombstone
WHERE org_id = #{orgId}
